<?php

use App\Http\Controllers\CajasController;
use App\Http\Controllers\CashCutController;
use App\Http\Controllers\CashCutCorrectionController;
use App\Http\Controllers\CashDifferenceController;
use App\Http\Controllers\CashDisbursementCorrectionController;
use App\Http\Controllers\CashLoanConversionController;
use App\Http\Controllers\CashManualCorrectionController;
use App\Http\Controllers\CashMovementController;
use App\Http\Controllers\CashOffsetCorrectionController;
use App\Http\Controllers\CashPendingDisbursementController;
use App\Http\Controllers\CashReconciliationController;
use App\Http\Controllers\CashTransferCorrectionController;
use App\Http\Middleware\EnsureApplicationAccess;
use Illuminate\Support\Facades\Route;

Route::middleware(['auth', EnsureApplicationAccess::class.':cajas'])->prefix('cajas')->name('cajas.')->group(function (): void {
    Route::get('/', [CajasController::class, 'home'])->name('home');
    Route::get('/cobros', [CajasController::class, 'collections'])->name('collections');
    Route::get('/cobros/creditos-pendientes', [CashLoanConversionController::class, 'index'])->name('credits.index');
    Route::get('/cobros/cortes/{cut}/creditos/{credit}/entregar', [CashPendingDisbursementController::class, 'create'])->name('disbursements.create');
    Route::post('/cobros/cortes/{cut}/creditos/{credit}/entregar', [CashPendingDisbursementController::class, 'store'])->name('disbursements.store');
    Route::get('/cobros/cortes/{cut}/creditos/{credit}', [CashLoanConversionController::class, 'show'])->name('credits.show');
    Route::post('/cobros/cortes/{cut}/creditos/{credit}/convertir', [CashLoanConversionController::class, 'store'])->name('credits.store');
    Route::get('/cobros/nuevo', [CashCutController::class, 'create'])->name('cuts.create');
    Route::post('/cobros/cortes', [CashCutController::class, 'store'])->name('cuts.store');
    Route::get('/cobros/cortes/{cut}', [CashCutController::class, 'show'])->name('cuts.show');
    Route::get('/cobros/cortes/{cut}/letras', [CashCutController::class, 'conceptForm'])->defaults('kind', 'letters')->name('cuts.letters-form');
    Route::post('/cobros/cortes/{cut}/letras', [CashCutController::class, 'letters'])->name('cuts.letters');
    Route::get('/cobros/cortes/{cut}/adelanto', [CashCutController::class, 'conceptForm'])->defaults('kind', 'advance')->name('cuts.advance-form');
    Route::post('/cobros/cortes/{cut}/adelanto', [CashCutController::class, 'advance'])->name('cuts.advance');
    Route::post('/cobros/cortes/{cut}/retirar/{type}/{item}', [CashCutController::class, 'remove'])->name('cuts.remove');
    Route::get('/cobros/cortes/{cut}/credito', [CashCutController::class, 'creditForm'])->name('cuts.credit-form');
    Route::post('/cobros/cortes/{cut}/credito/cotizar', [CashCutController::class, 'quote'])->name('cuts.credit-quote');
    Route::post('/cobros/cortes/{cut}/credito', [CashCutController::class, 'creditStore'])->name('cuts.credit-store');
    Route::post('/cobros/cortes/{cut}/credito/{item}/autorizar', [CashCutController::class, 'creditAuthorize'])->name('cuts.credit-authorize');
    Route::get('/cobros/cortes/{cut}/entrega', [CashCutController::class, 'receiptForm'])->name('cuts.receipt-form');
    Route::post('/cobros/cortes/{cut}/entrega', [CashCutController::class, 'receive'])->name('cuts.receive');
    Route::get('/cobros/cortes/{cut}/enviar', [CashCutController::class, 'reviewForm'])->defaults('step', 'send')->name('cuts.submit-form');
    Route::post('/cobros/cortes/{cut}/enviar', [CashCutController::class, 'submit'])->name('cuts.submit');
    Route::get('/cobros/cortes/{cut}/revision', [CashCutController::class, 'reviewForm'])->defaults('step', 'review')->name('cuts.review-form');
    Route::post('/cobros/cortes/{cut}/revision/{action}', [CashCutController::class, 'review'])->name('cuts.review');
    Route::get('/cobros/cortes/{cut}/corregir/{kind}/{target}', [CashCutCorrectionController::class, 'create'])->name('corrections.create');
    Route::post('/cobros/cortes/{cut}/corregir/{kind}/{target}', [CashCutCorrectionController::class, 'preview'])->name('corrections.preview');
    Route::post('/cobros/cortes/{cut}/correcciones', [CashCutCorrectionController::class, 'store'])->name('corrections.store');
    Route::get('/cobros/cortes/{cut}/correcciones/{correction}', [CashCutCorrectionController::class, 'show'])->name('corrections.show');
    Route::post('/cobros/cortes/{cut}/correcciones/{correction}/{action}', [CashCutCorrectionController::class, 'resolve'])->name('corrections.resolve');
    Route::get('/cobros/cortes/{cut}/creditos/{credit}/corregir-capital/{kind}', [CashDisbursementCorrectionController::class, 'create'])->name('capital-corrections.create');
    Route::post('/cobros/cortes/{cut}/creditos/{credit}/corregir-capital/{kind}', [CashDisbursementCorrectionController::class, 'preview'])->name('capital-corrections.preview');
    Route::post('/cobros/cortes/{cut}/creditos/{credit}/solicitudes-capital', [CashDisbursementCorrectionController::class, 'store'])->name('capital-corrections.store');
    Route::get('/cobros/cortes/{cut}/creditos/{credit}/solicitudes-capital/{correction}', [CashDisbursementCorrectionController::class, 'show'])->name('capital-corrections.show');
    Route::post('/cobros/cortes/{cut}/creditos/{credit}/solicitudes-capital/{correction}/{action}', [CashDisbursementCorrectionController::class, 'resolve'])->name('capital-corrections.resolve');
    Route::get('/cobros/cortes/{cut}/creditos/{credit}/corregir-compensacion/{kind}', [CashOffsetCorrectionController::class, 'create'])->name('offset-corrections.create');
    Route::post('/cobros/cortes/{cut}/creditos/{credit}/corregir-compensacion/{kind}', [CashOffsetCorrectionController::class, 'preview'])->name('offset-corrections.preview');
    Route::post('/cobros/cortes/{cut}/creditos/{credit}/solicitudes-compensacion', [CashOffsetCorrectionController::class, 'store'])->name('offset-corrections.store');
    Route::get('/cobros/cortes/{cut}/creditos/{credit}/solicitudes-compensacion/{correction}', [CashOffsetCorrectionController::class, 'show'])->name('offset-corrections.show');
    Route::post('/cobros/cortes/{cut}/creditos/{credit}/solicitudes-compensacion/{correction}/{action}', [CashOffsetCorrectionController::class, 'resolve'])->name('offset-corrections.resolve');
    Route::get('/cuentas', [CajasController::class, 'accounts'])->name('accounts');
    Route::get('/cuentas/{account}', [CajasController::class, 'account'])->name('accounts.show');
    Route::get('/cuentas/{account}/arqueos/nuevo', [CashReconciliationController::class, 'create'])->name('reconciliations.create');
    Route::post('/cuentas/{account}/arqueos', [CashReconciliationController::class, 'store'])->name('reconciliations.store');
    Route::get('/cuentas/{account}/arqueos/{reconciliation}', [CashReconciliationController::class, 'show'])->name('reconciliations.show');
    Route::get('/cuentas/{account}/arqueos/{reconciliation}/aclarar', [CashDifferenceController::class, 'create'])->name('differences.create');
    Route::post('/cuentas/{account}/arqueos/{reconciliation}/aclarar', [CashDifferenceController::class, 'preview'])->name('differences.preview');
    Route::post('/cuentas/{account}/arqueos/{reconciliation}/aclaraciones', [CashDifferenceController::class, 'store'])->name('differences.store');
    Route::get('/cuentas/{account}/arqueos/{reconciliation}/aclaraciones/{resolution}', [CashDifferenceController::class, 'show'])->name('differences.show');
    Route::post('/cuentas/{account}/arqueos/{reconciliation}/aclaraciones/{resolution}/{action}', [CashDifferenceController::class, 'resolve'])->name('differences.resolve');
    Route::post('/cuentas/{account}/arqueos/{reconciliation}/{action}', [CashReconciliationController::class, 'resolve'])->name('reconciliations.resolve');
    Route::get('/configuracion', [CajasController::class, 'settings'])->name('settings');
    Route::post('/configuracion/cuentas', [CajasController::class, 'storeAccount'])->name('accounts.store');
    Route::put('/configuracion/cuentas/{account}', [CajasController::class, 'updateAccount'])->name('accounts.update');
    Route::put('/configuracion/cuentas/{account}/destinos', [CajasController::class, 'updateDestinations'])->name('accounts.destinations');
    Route::get('/configuracion/accesos/{user}', [CajasController::class, 'access'])->name('access');
    Route::put('/configuracion/accesos/{user}', [CajasController::class, 'updateAccess'])->name('access.update');
    Route::get('/cuentas/{account}/nuevo/{kind}', [CashMovementController::class, 'create'])->name('movements.create');
    Route::post('/cuentas/{account}/movimientos/{kind}', [CashMovementController::class, 'store'])->name('movements.store');
    Route::get('/movimientos/{operation}/corregir/{kind}', [CashTransferCorrectionController::class, 'create'])->name('transfer-corrections.create');
    Route::post('/movimientos/{operation}/corregir/{kind}', [CashTransferCorrectionController::class, 'preview'])->name('transfer-corrections.preview');
    Route::post('/movimientos/{operation}/solicitudes', [CashTransferCorrectionController::class, 'store'])->name('transfer-corrections.store');
    Route::get('/movimientos/{operation}/solicitudes/{correction}', [CashTransferCorrectionController::class, 'show'])->name('transfer-corrections.show');
    Route::post('/movimientos/{operation}/solicitudes/{correction}/{action}', [CashTransferCorrectionController::class, 'resolve'])->name('transfer-corrections.resolve');
    Route::get('/movimientos/{operation}/corregir-manual/{kind}', [CashManualCorrectionController::class, 'create'])->name('manual-corrections.create');
    Route::post('/movimientos/{operation}/corregir-manual/{kind}', [CashManualCorrectionController::class, 'preview'])->name('manual-corrections.preview');
    Route::post('/movimientos/{operation}/solicitudes-manuales', [CashManualCorrectionController::class, 'store'])->name('manual-corrections.store');
    Route::get('/movimientos/{operation}/solicitudes-manuales/{correction}', [CashManualCorrectionController::class, 'show'])->name('manual-corrections.show');
    Route::post('/movimientos/{operation}/solicitudes-manuales/{correction}/{action}', [CashManualCorrectionController::class, 'resolve'])->name('manual-corrections.resolve');
    Route::get('/movimientos/{operation}', [CashMovementController::class, 'show'])->name('operations.show');
    Route::get('/movimientos/{operation}/confirmar/{action}', [CashMovementController::class, 'transitionForm'])
        ->whereIn('action', ['deliver', 'accept'])->name('operations.transition-form');
    Route::post('/movimientos/{operation}/{action}', [CashMovementController::class, 'transition'])->name('operations.transition');
});
